class LabelService {
  static async generateLabel(lot) {
    return render([lot], `Etichet\u0103 lot ${lot.lot_number}`);
  }
  static async generateBatchLabels(lots) {
    if (lots.length === 0)
      throw new Error("No lots to label");
    return render(lots, `Etichete \u2014 ${lots.length} loturi`);
  }
}

